+    let index = semantic_index(db, program_file);
+    let env = ProgramEnvironment::from_file(program_file);
+    TypeInferenceBuilder::new(
+        db,
+        &env,
+        InferenceRegion::Definition(definition),
+        python_file.file(db),
+        program_file,
+        index,
+        &module,
